// Normalise all incoming messages to a consistent format regardless of source
const item = $input.first().json;

return [{
  json: {
    message_id: item.message_id || item.id || item.email_id || Date.now().toString(),
    channel: item.channel || item.source || 'unknown',
    customer_name: item.customer_name || item.from_name || item.sender_name || 'Customer',
    customer_email: item.customer_email || item.from_email || item.email || null,
    customer_phone: item.customer_phone || item.from_number || item.phone || null,
    customer_id: item.customer_id || item.contact_id || null,
    message_text: item.message || item.body || item.text || item.content || '',
    message_timestamp: item.timestamp || item.date || new Date().toISOString(),
    thread_id: item.thread_id || item.conversation_id || item.message_id || null,
    attachments: item.attachments || item.files || [],
    previous_messages: item.history || item.thread_history || [],
    metadata: item.metadata || {}
  }
}];

// Route reply back to the correct channel
const channel = $('normalise-message').item.json.channel;
const reply = $('claude-classify').item.json.resolution_reply;
const customer_email = $('normalise-message').item.json.customer_email;
const customer_phone = $('normalise-message').item.json.customer_phone;
const thread_id = $('normalise-message').item.json.thread_id;

return [{ json: { channel, reply, customer_email, customer_phone, thread_id, auto_sent: true } }];

